use bhoo::*;
mod fixture {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_multi_autocomplete.rs"));}
const VIEW:Rect=Rect{x:0.,y:0.,width:300.,height:400.};
fn draw(ui:&mut Ui,state:&mut android_xml::LayoutState,input:Input)->Option<&'static str>{let mut action=None;ui.frame(input,VIEW,0.,|f|{action=fixture::LAYOUT.render(f,Rect{x:0.,y:0.,width:300.,height:64.},state);});action}
fn setup()->(Ui,android_xml::LayoutState){let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();state.set_autocomplete_items("cities",["San Diego","San Francisco","New York"].into_iter().map(str::to_owned).collect());draw(&mut ui,&mut state,Input::default());ui.adapter_focus(Some(android_xml::view_id("cities")));(ui,state)}
fn choose(ui:&mut Ui,state:&mut android_xml::LayoutState,label:&str){let item=ui.semantics().iter().find(|n|n.label.as_ref()==label).unwrap().bounds;let point=[item.x+10.,item.y+10.];draw(ui,state,Input{pointer:Some(point),pressed:true,time:0.2,..Input::default()});assert_eq!(draw(ui,state,Input{pointer:Some(point),released:true,time:0.3,..Input::default()}),Some("cities"));}
#[test] fn tokenizer_required_and_threshold_per_token(){let (mut ui,mut state)=setup();state.text.insert("cities".into(),"Paris, s".into());draw(&mut ui,&mut state,Input::default());assert!(!ui.semantics().iter().any(|n|n.label.as_ref()=="San Diego"));state.comma_tokenizers.insert("cities".into());draw(&mut ui,&mut state,Input::default());assert!(!ui.semantics().iter().any(|n|n.label.as_ref()=="San Diego"));state.text.insert("cities".into(),"Paris, sa".into());draw(&mut ui,&mut state,Input::default());assert!(ui.semantics().iter().any(|n|n.label.as_ref()=="San Diego"));choose(&mut ui,&mut state,"San Diego");assert_eq!(state.text["cities"],"Paris, San Diego, ");}
#[test] fn selection_in_middle_preserves_following_text_and_utf16_offsets(){let (mut ui,mut state)=setup();state.comma_tokenizers.insert("cities".into());state.text.insert("cities".into(),"😀, sa, Tokyo".into());state.text_selection_end.insert("cities".into(),6);draw(&mut ui,&mut state,Input::default());choose(&mut ui,&mut state,"San Francisco");assert_eq!(state.text["cities"],"😀, San Francisco, , Tokyo");assert_eq!(state.text_selection_end["cities"],19);}
